using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using LeadPilot;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
var b=WebApplication.CreateBuilder(args);var jwt=b.Configuration["JWT_SECRET"]??throw new Exception("JWT_SECRET required");if(jwt.Length<32)throw new Exception("JWT_SECRET too short");if((b.Configuration["ENCRYPTION_KEY"]??"").Length<32)throw new Exception("ENCRYPTION_KEY required (32+ chars)");b.Services.AddDbContext<CrmDb>(o=>o.UseNpgsql(b.Configuration.GetConnectionString("Db")??throw new Exception("DB required")));b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=true,ValidIssuer="leadpilot",ValidateAudience=true,ValidAudience="leadpilot",ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt)),ValidateLifetime=true});b.Services.AddAuthorization();b.Services.AddHttpClient();b.Services.AddScoped<Integrations>();b.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins(b.Configuration["WEB_ORIGIN"]??"http://localhost:3000").AllowAnyHeader().AllowAnyMethod()));var app=b.Build();if(args.Contains("--migrate")){using var scope=app.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<CrmDb>();await db.Database.MigrateAsync();if(b.Configuration.GetValue<bool>("DEMO_MODE")&&!await db.Organizations.AnyAsync()){var org=new Organization{Name="Студия Север"};db.Organizations.Add(org);var email=b.Configuration["DEMO_EMAIL"]??throw new Exception("DEMO_EMAIL required");var password=b.Configuration["DEMO_PASSWORD"]??throw new Exception("DEMO_PASSWORD required");db.Agents.Add(new Agent{OrganizationId=org.Id,Email=email,Name="Алексей",Role="Owner",PasswordHash=Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(password,Encoding.UTF8.GetBytes(email),210000,HashAlgorithmName.SHA256,32))});foreach(var kind in new[]{"telegram","vk","max"}){var channel=new Channel{OrganizationId=org.Id,Kind=kind,ExternalId="demo-"+kind};db.Channels.Add(channel);var contact=new Contact{OrganizationId=org.Id,ChannelId=channel.Id,Name="Клиент "+kind,ExternalId="de