string Token(Agent a)=>new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken("leadpilot","leadpilot",[new Claim(ClaimTypes.NameIdentifier,a.Id.ToString()),new Claim("org",a.OrganizationId.ToString()),new Claim(ClaimTypes.Role,a.Role)],expires:DateTime.UtcNow.AddHours(8),signingCredentials:new(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt)),SecurityAlgorithms.HmacSha256)));

app.MapPost("/api/auth/register",async(Register x,CrmDb db)=>{if(x.Password.Length<12||x.Email.Length>254||x.Organization.Length is <2 or >120)return Results.BadRequest();if(await db.Agents.AnyAsync(y=>y.Email==x.Email))return Results.Conflict();var org=new Organization{Name=x.Organization};db.Organizations.Add(org);var agent=new Agent{OrganizationId=org.Id,Email=x.Email,Name=x.Email,PasswordHash=Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(x.Password,Encoding.UTF8.GetBytes(x.Email),210000,HashAlgorithmName.SHA256,32))};db.Agents.Add(agent);await db.SaveChangesAsync();return Results.Ok(new{token=Token(agent)});});
app.MapPost("/api/auth/login",async(Login x,CrmDb db)=>{var a=await db.Agents.SingleOrDefaultAsync(y=>y.Email==x.Email);if(a==null||!CryptographicOperations.FixedTimeEquals(Convert.FromBase64String(a.PasswordHash),Rfc2898DeriveBytes.Pbkdf2(x.Password,Encoding.UTF8.GetBytes(x.Email),210000,HashAlgorithmName.SHA256,32)))return Results.Unauthorized();return Results.Ok(new{token=Token(a),role=a.Role});});
app.MapGet("/api/config",()=>new{demoMode=b.Configuration.GetValue<bool>("DEMO_MODE")});
var api=app.MapGroup("/api").RequireAuthorization();
api.MapGet("/organizations/me",async(ClaimsPrincipal u,CrmDb db)=>await db.Organizations.Where(x=>x.Id==Guid.Parse(u.FindFirstValue("org")!)).Select(x=>new{x.Id,x.Name,x.AutoReply,x.MonthlyAiLimit,x.AiCalls}).SingleAsync());
api.MapPut("/organizations/settings",async(SettingsInput x,ClaimsPrincipal u,CrmDb db)=>{if(!u.IsInRole("Owner"))return Results.Forbid();var org=await db.Organizations.SingleAsync(y=>y.Id==Guid.Parse(u.FindFirstValue("org")!));org.AutoReply=x.AutoReply;org.MonthlyAiLimit=Math.Clamp(x.MonthlyAiLimit,0,10000);await db.SaveChangesAsync();return Results.Ok(new{org.AutoReply,org.MonthlyAiLimit});});
api.MapGet("/agents",(ClaimsPrincipal u,CrmDb db)=>db.Agents.Where(x=>x.OrganizationId==Guid.Parse(u.FindFirstValue("org")!)).Select(x=>new{x.Id,x.Name,x.Role}));
api.MapPost("/agents",async(AgentInput x,ClaimsPrincipal u,CrmDb db)=>{if(!u.IsInRole("Owner")||!new[]{"Admin","Manager"}.Contains(x.Role)||x.Password.Length<12)return Results.BadRequest();var a=new Agent{OrganizationId=Guid.Parse(u.FindFirstValue("org")!),Email=x.Email,Name=x.Name,Role=x.Role,PasswordHash=Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(x.Password,Encoding.UTF8.GetBytes(x.Email),210000,HashAlgorithmName.SHA256,32))};db.Agents.Add(a);await db.SaveChangesAsync();return Results.Ok(new{a.Id,a.Name,a.Role});});
api.MapGet("/channels",(ClaimsPrincipal u,CrmDb db)=>db.Channels.Where(x=>x.OrganizationId==Guid.Parse(u.FindFirstValue("org")!)).Select(x=>new{x.Id,x.Kind,x.ExternalId,x.Active}));
api.MapPost("/channels",async(ChannelInput x,ClaimsPrincipal u,CrmDb db,Integrations adapter)=>{if(!u.IsInRole("Owner")||!new[]{"telegram","vk","max"}.Contains(x.Kind)||string.IsNullOrWhiteSpace(x.Token)||x.WebhookSecret.Length<16)return Results.BadRequest();var channel=new Channel{OrganizationId=Guid.Parse(u.FindFirstValue("org")!),Kind=x.Kind,ExternalId=x.ExternalId,SecretEncrypted=adapter.Encrypt(x.Token),WebhookSecretEncrypted=adapter.Encrypt(x.WebhookSecret)};db.Channels.Add(channel);await db.SaveChangesAsync();return Results.Ok(new{channel.Id,channel.Kind,channel.ExternalId});});
api.MapGet("/contacts",(ClaimsPrincipal u,CrmDb db,int? page)=>db.Contacts.Where(x=>x.OrganizationId==Guid.Parse(u.FindFirstValue("org")!)).OrderBy(x=>x.Name).Skip((Math.Clamp(page??1,1,1000)-1)*50).Take(50));
api.MapGet("/conversations",(ClaimsPrincipal u,CrmDb db,string? status,int? page)=>db.Conversations.Where(x=>x.OrganizationId==Guid.Parse(u.FindFirstValue("org")!)&&(status==null||x.Status==status)).OrderByDescending(x=>x.UpdatedAt).Skip((Math.Clamp(page??1,1,1000)-1)*50).Take(50));
api.MapGet("/conversations/{id:guid}/messages",(Guid id,ClaimsPrincipal u,CrmDb db,int? page)=>db.Messages.Where(x=>x.OrganizationId==Guid.Parse(u.FindFirstValue("org")!)&&x.ConversationId==id).OrderByDescending(x=>x.CreatedAt).Skip((Math.Clamp(page??1,1,1000)-1)*50).Take(50));
api.MapPatch("/conversations/{id:guid}",async(Guid id,AssignInput x,ClaimsPrincipal u,CrmDb db)=>{var c=await db.Conversations.SingleOrDefaultAsync(y=>y.Id==id&&y.OrganizationId==Guid.Parse(u.FindFirstValue("org")!));if(c==null)return Results.NotFound();if(!new[]{"open","closed","human"}.Contains(x.Status))return Results.BadRequest();if(x.AgentId.HasValue&&!await db.Agents.AnyAsync(y=>y.Id==x.AgentId&&y.OrganizationId==Guid.Parse(u.FindFirstValue("org")!)))return Results.BadRequest();c.Status=x.Status;c.AssignedAgentId=x.AgentId;db.Audits.Add(new Audit{OrganizationId=Guid.Parse(u.FindFirstValue("org")!),AgentId=Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!),Action="conversation.update:"+id});await db.SaveChangesAsync();return Results.Ok(c);});
api.MapPost("/conversations/{id:guid}/messages",async(Guid id,Reply x,ClaimsPrincipal u,CrmDb db,Integrations adapter)=>{if(x.Body.Length is <1 or >4000)return Results.BadRequest();var c=await db.Conversations.SingleOrDefaultAsync(y=>y.Id==id&&y.OrganizationId==Guid.Parse(u.FindFirstValue("org")!));if(c==null)return Results.NotFound();var contact=await db.Contacts.SingleAsync(y=>y.Id==c.ContactId);var channel=await db.Channels.SingleAsync(y=>y.Id==c.ChannelId);if(!b.Configuration.GetValue<bool>("DEMO_MODE"))await adapter.Send(channel,contact.ExternalId,x.Body);var m=new Message{OrganizationId=Guid.Parse(u.FindFirstValue("org")!),ConversationId=id,Body=x.Body,Direction="outgoing",ExternalId="operator:"+Guid.NewGuid()};db.Messages.Add(m);c.UpdatedAt=DateTime.UtcNow;db.Audits.Add(new Audit{OrganizationId=Guid.Parse(u.FindFirstValue("org")!),AgentId=Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!),Action="message.send:"+id});await db.SaveChangesAsync();return Results.Ok(m);});
api.MapGet("/leads",(ClaimsPrincipal u,CrmDb db,string? stage,int? page)=>db.Leads.Where(x=>x.OrganizationId==Guid.Parse(u.FindFirstValue("org")!)&&(stage==null||x.Stage==stage)).OrderByDescending(x=>x.CreatedAt).Skip((Math.Clamp(page??1,1,1000)-1)*50).Take(50));
api.MapPost("/leads",async(LeadInput x,ClaimsPrincipal u,CrmDb db)=>{if(!await db.Contacts.AnyAsync(y=>y.Id==x.ContactId&&y.OrganizationId==Guid.Parse(u.FindFirstValue("org")!))||x.Value<0)return Results.BadRequest();var lead=new Lead{OrganizationId=Guid.Parse(u.FindFirstValue("org")!),ContactId=x.ContactId,Name=x.Name,Value=x.Value};db.Leads.Add(lead);db.Audits.Add(new Audit{OrganizationId=Guid.Parse(u.FindFirstValue("org")!),AgentId=Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!),Action="lead.create:"+lead.Id});await db.SaveChangesAsync();return Results.Ok(lead);});
api.MapPatch("/leads/{id:guid}",async(Guid id,StageInput x,ClaimsPrincipal u,CrmDb db)=>{if(!new[]{"new","contacted","qualified","won","lost"}.Contains(x.Stage))return Results.BadRequest();var lead=await db.Leads.SingleOrDefaultAsync(y=>y.Id==id&&y.OrganizationId==Guid.Parse(u.FindFirstValue("org")!));if(lead==null)return Results.NotFound();lead.Stage=x.Stage;db.Audits.Add(new Audit{OrganizationId=Guid.Parse(u.FindFirstValue("org")!),AgentId=Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!),Action="lead.stage:"+id+":"+x.Stage});await db.SaveChangesAsync();return Results.Ok(lead);});
api.MapPost("/integrations/{system}/leads/{id:guid}",async(string system,Guid id,ClaimsPrincipal u,CrmDb db,Integrations adapter)=>{if(!u.IsInRole("Owner")&&!u.IsInRole("Admin"))return Results.Forbid();var lead=await db.Leads.SingleOrDefaultAsync(y=>y.Id==id&&y.OrganizationId==Guid.Parse(u.FindFirstValue("org")!));if(lead==null)return Results.NotFound();var contact=await db.Contacts.SingleAsync(y=>y.Id==lead.ContactId);await adapter.SyncLead(lead,contact,system);return Results.Ok(new{synced=true});});
api.MapGet("/analytics",async(ClaimsPrincipal u,CrmDb db)=>{var org=Guid.Parse(u.FindFirstValue("org")!);return new{Conversations=await db.Conversations.CountAsync(x=>x.OrganizationId==org),Leads=await db.Leads.CountAsync(x=>x.OrganizationId==org),Won=await db.Leads.CountAsync(x=>x.OrganizationId==org&&x.Stage=="won")};});
api.MapGet("/audit",(ClaimsPrincipal u,CrmDb db)=>db.Audits.Where(x=>x.OrganizationId==Guid.Parse(u.FindFirstValue("org")!)).OrderByDescending(x=>x.CreatedAt).Take(100));
async Task<HttpResponseMessage> Ai(HttpClient client,Guid org,string path,HttpContent? content=null){client.DefaultRequestHeaders.Add("X-Internal-Token",b.Configuration["AI_INTERNAL_TOKEN"]);client.DefaultRequestHeaders.Add("X-Organization",org.ToString());return content is null?await client.GetAsync("http://ai:8000"+path):await client.PostAsync("http://ai:8000"+path,content);}
api.MapGet("/knowledge",async(ClaimsPrincipal u,IHttpClientFactory clients)=>{var response=await Ai(clients.CreateClient(),Guid.Parse(u.FindFirstValue("org")!),"/documents");return Results.Content(await response.Content.ReadAsStringAsync(),"application/json",statusCode:(int)response.StatusCode);});
api.MapGet("/knowledge/search",async(string q,ClaimsPrincipal u,IHttpClientFactory clients)=>{var response=await Ai(clients.CreateClient(),Guid.Parse(u.FindFirstValue("org")!),"/search?q="+Uri.EscapeDataString(q));return Results.Content(await response.Content.ReadAsStringAsync(),"application/json",statusCode:(int)response.StatusCode);});
api.MapPost("/knowledge",async(HttpRequest request,ClaimsPrincipal u,IHttpClientFactory clients)=>{if(!request.HasFormContentType)return Results.BadRequest();var file=(await request.ReadFormAsync()).Files.FirstOrDefault();if(file==null||file.Length>5_000_000)return Results.BadRequest();using var data=new MultipartFormDataContent();data.Add(new StreamContent(file.OpenReadStream()),"file",Path.GetFileName(file.FileName));var response=await Ai(clients.CreateClient(),Guid.Parse(u.FindFirstValue("org")!),"/documents",data);return Results.Content(await response.Content.ReadAsStringAsync(),"application/json",statusCode:(int)response.StatusCode);});
api.MapPost("/ai/preview",async(AiRequest x,ClaimsPrincipal u,CrmDb db,IHttpClientFactory clients)=>{var org=await db.Organizations.SingleAsync(y=>y.Id==Guid.Parse(u.FindFirstValue("org")!));if(org.AiResetAt.Month!=DateTime.UtcNow.Month||org.AiResetAt.Year!=DateTime.UtcNow.Year){org.AiCalls=0;org.AiResetAt=DateTime.UtcNow;}if(org.AiResetAt.Month!=DateTime.UtcNow.Month||org.AiResetAt.Year!=DateTime.UtcNow.Year){org.AiCalls=0;org.AiResetAt=DateTime.UtcNow;await db.SaveChangesAsync();}if(await db.Organizations.Where(y=>y.Id==org.Id&&y.AiCalls<y.MonthlyAiLimit).ExecuteUpdateAsync(y=>y.SetProperty(z=>z.AiCalls,z=>z.AiCalls+1))==0)return Results.StatusCode(429);var response=await Ai(clients.CreateClient(),org.Id,"/preview",JsonContent.Create(new{question=x.Question}));if(!response.IsSuccessStatusCode)return Results.Content(await response.Content.ReadAsStringAsync(),"application/json",statusCode:(int)response.StatusCode);return Results.Content(await response.Content.ReadAsStringAsync(),"application/json");});
app.MapPost("/api/webhooks/{channelId:guid}",async(Guid channelId,HttpRequest request,CrmDb db,Integrations adapter)=>{var channel=await db.Channels.SingleOrDefaultAsync(x=>x.Id==channelId&&x.Active);if(channel==null)return Results.NotFound();using var doc=await JsonDocument.ParseAsync(request.Body);var root=doc.RootElement;var provided=request.Headers["X-Telegram-Bot-Api-Secret-Token"].FirstOrDefault()??request.Headers["X-Channel-Secret"].FirstOrDefault()??(channel.Kind=="vk"&&root.TryGetProperty("secret",out var vkSecret)?vkSecret.GetString():null)??"";var expected=adapter.Decrypt(channel.WebhookSecretEncrypted);if(provided.Length!=expected.Length||!CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(provided),Encoding.UTF8.GetBytes(expected)))return Results.Unauthorized();if(channel.Kind=="vk"&&root.TryGetProperty("type",out var eventType)&&eventType.GetString()=="confirmation")return Results.Text(b.Configuration["VK_CONFIRMATION_CODE"]??"");string external,body,name,messageId;if(channel.Kind=="telegram"){var message=root.GetProperty("message");external=message.GetProperty("chat").GetProperty("id").ToString();body=message.TryGetProperty("text",out var text)?text.GetString()??"":"";name=message.GetProperty("from").TryGetProperty("first_name",out var first)?first.GetString()??"Клиент":"Клиент";messageId=message.GetProperty("message_id").ToString();}else if(channel.Kind=="vk"){var message=root.GetProperty("object").GetProperty("message");external=message.GetProperty("peer_id").ToString();body=message.GetProperty("text").GetString()??"";name="Клиент VK";messageId=message.GetProperty("id").ToString();}else{var message=root.GetProperty("message");external=message.GetProperty("recipient").GetProperty("chat_id").ToString();body=message.GetProperty("body").GetProperty("text").GetString()??"";name="Клиент MAX";messageId=message.GetProperty("mid").ToString();}if(body.Length>4000)body=body[..4000];var contact=await db.Contacts.SingleOrDefaultAsync(x=>x.ChannelId==channelId&&x.ExternalId==external);if(contact==null){contact=new Contact{OrganizationId=channel.OrganizationId,ChannelId=channelId,ExternalId=external,Name=name};db.Contacts.Add(contact);}var conversation=await db.Conversations.SingleOrDefaultAsync(x=>x.OrganizationId==channel.OrganizationId&&x.ContactId==contact.Id);if(conversation==null){conversation=new Conversation{OrganizationId=channel.OrganizationId,ChannelId=channelId,ContactId=contact.Id};db.Conversations.Add(conversation);}if(await db.Messages.AnyAsync(x=>x.ConversationId==conversation.Id&&x.ExternalId==messageId))return Results.Ok();db.Messages.Add(new Message{OrganizationId=channel.OrganizationId,ConversationId=conversation.Id,ExternalId=messageId,Body=body});conversation.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();
 var org=await db.Organizations.SingleAsync(x=>x.Id==channel.OrganizationId);
 if(org.AiResetAt.Month!=DateTime.UtcNow.Month||org.AiResetAt.Year!=DateTime.UtcNow.Year){org.AiCalls=0;org.AiResetAt=DateTime.UtcNow;}if(org.AutoReply&&conversation.Status=="open"&&!b.Configuration.GetValue<bool>("DEMO_MODE")&&!string.IsNullOrWhiteSpace(b.Configuration["LLM_API_KEY"])&&org.AiCalls<org.MonthlyAiLimit&&body.Length>=3){
  try{var client=app.Services.GetRequiredService<IHttpClientFactory>().CreateClient();var result=await Ai(client,org.Id,"/preview",JsonContent.Create(new{question=body}));if(result.IsSuccessStatusCode){using var preview=JsonDocument.Parse(await result.Content.ReadAsStringAsync());var sources=preview.RootElement.GetProperty("sources");var answer=preview.RootElement.GetProperty("answer").GetString();if(sources.GetArrayLength()>0&&!string.IsNullOrWhiteSpace(answer)&&answer.Length<=4000){await adapter.Send(channel,external,answer);db.Messages.Add(new Message{OrganizationId=org.Id,ConversationId=conversation.Id,Body=answer,ExternalId="auto:"+Guid.NewGuid(),Direction="outgoing"});await db.Organizations.Where(y=>y.Id==org.Id&&y.AiCalls<y.MonthlyAiLimit).ExecuteUpdateAsync(y=>y.SetProperty(z=>z.AiCalls,z=>z.AiCalls+1));await db.SaveChangesAsync();}}}catch(Exception ex){app.Logger.LogError(ex,"Автоответ не отправлен для диалога {ConversationId}",conversation.Id);}
 }return Results.Ok();});
app.Run();
record Register(string Email,string Password,string Organization);record Login(string Email,string Password);record SettingsInput(bool AutoReply,int MonthlyAiLimit);record AgentInput(string Email,string Password,string Name,string Role);record ChannelInput(string Kind,string ExternalId,string Token,string WebhookSecret);record AssignInput(string Status,Guid? AgentId);record Reply(string Body);record LeadInput(Guid ContactId,string Name,decimal Value);record StageInput(string Stage);record AiRequest(string Question);
